    if (op === '+') return a + b;
    if (op === '-') return a - b;
    if (op === '*') return a * b;
    if (b === 0n) return 0n;
    return a / b;
  }

  function ev(t) {
    let d = 0, split = -1;
    for (let k = t.length - 1; k >= 0; k--) {
      const c = t[k];
      if (c === ')') d++;
      else if (c === '(') d--;
