        else if (d === 0 && (c === '*' || c === '/')) { split = k; break; }
      }
    }
    if (split !== -1) {
      const left = ev(t.slice(0, split));
      const right = ev(t.slice(split + 1));
      return calc(left, t[split], right);
    }
    if (t[0] === '(') return ev(t.slice(1, -1));
    return BigInt(t);
  }

