function solve(s) {
  const src = s.replace(/\s+/g, '');
  let i = 0, depth = 0, need = true, ok = true;
  while (i < src.length) {
    const c = src[i];
    if (c >= '0' && c <= '9') {
      if (!need) { ok = false; break; }
      while (i < src.length && src[i] >= '0' && src[i] <= '9') i++;
