    } else if (c === ')') {
      if (need || depth === 0) { ok = false; break; }
      depth--; i++;
    } else if (c === '+' || c === '-' || c === '*' || c === '/') {
      if (need) { ok = false; break; }
      need = true; i++;
    } else { ok = false; break; }
  }
  if (!ok || need || depth !== 0) return "0";

  const prec = { '+': 1, '-': 1, '*': 2, '/': 2 };
  const vals = [], ops = [];

  function calc(a, op, b) {
    if (op === '+') return a + b;
    if (op === '-') return a - b;
    if (op === '*') return a * b;
    if (b === 0n) return 0n;
    return a / b;
  }

  function apply() {
    const b = vals.pop(), a = vals.pop(), op = ops.pop();
    vals.push(calc(a, op, b));
  }

  i = 0;
  while (i < src.length) {
    const c = src[i];
    if (c >= '0' && c <= '9') {
      let j = i;
      while (j < src.length && src[j] >= '0' && src[j] <= '9') j++;
      vals.push(BigInt(src.slice(i, j)));
      i = j;
    } else if (c === '(') {
      ops.push(c); i++;
    } else if (c === ')') {
      while (ops[ops.length - 1] !== '(') apply();
      ops.pop(); i++;
    } else {
      while (ops.length > 0 && ops[ops.length - 1] !== '(' && prec[ops[ops.length - 1]] >= prec[c]) apply();
      ops.push(c); i++;
    }
  }
  while (ops.length > 0) apply();
  return vals[0].toString();
}
